A=R/'work/monthly_profitability141_local_annual_feasibility.json';F=json.loads(A.read_text());sources=[]
for x in F['annual_sources']:
 sources.append({k:x[k] for k in ['symbol','fiscal_year','fiscal_quarter','release_date','release_date_literal','fiscal_year_end','raw_path','raw_sha256','source_url','receipt_path','receipt_entry_key','receipt_sha256','retrieved_at','annual_duration_label','rows']})
