plan={'schema_version':1,'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'purpose':'Independent official issuer-statement raw annual facts; no financial ratio, rank, portfolio or return','output_dir':'outputs/monthly_profitability141_issuer_statements','separate_from_unchanged_SEC_DATA_PLAN':bind('outputs/monthly_profitability141_sources/DATA_PLAN.json'),'inputs':{'feasibility':bind(str(A.relative_to(R))),'identity_review':bind('work/profitability141_identity_admission_review.json'),'MSFT_events':bind('outputs/monthly_earnings_repair/microsoft/events.json'),'NVDA_events':bind('outputs/monthly_earnings_repair/nvidia/events.json'),'calendar_plan':bind('outputs/monthly_forward_guidance_preflight_v1/CALENDAR_PLAN.json'),'calendar_sessions':bind('outputs/monthly_forward_guidance_preflight_v1/SESSIONS.json')},'source_scope':{'symbols':['MSFT','NVDA'],'annual_fiscal_year_labels':list(range(2015,2027)),'sources':sources,'new_requests':0},'extraction_contract':{'source':'Read only the exact pinned local issuer HTML and existing receipt; verify both SHA and receipt URL/status/hash. Retain current-release annual columns only, no cross-release comparative backfill.','measure':'Explicit annual Gross profit or monetary Gross margin in the original consolidated GAAP income statement; reject summary percentage margin and all non-GAAP/reconciliation rows. No revenue-minus-cost reconstruction.','pair':'Same raw release, current fiscal annual end and same-end consolidated total assets. Both numerical values are exact Decimal strings in displayed units, with scale separately recorded.','GAAP':'Require consolidated statement identity plus explicit GAAP/as-reported context distinguishing it from reconciliations; preserve exact evidence text. Never infer GAAP from the word margin alone.','scale':'Require explicit statement-local in millions/in thousands; monetary dollars indicated by source table/context. Preserve currency literal and evidence. USD normalized only when an explicit U.S. dollar reporting context or original certified financial-statement unit establishes it; otherwise keep currency unresolved and retain raw pair as review candidate.','annual_dates':'Retain literal annual duration and all end-date headers. Explicit start wins. For Twelve Months Ended at calendar month end, a derived calendar start may be recorded, clearly labeled derived. For 52/53-week years do not subtract365: only derive day after explicitly shown prior fiscal-year end, with separate derivation basis and review flag. Never claim a derived date was quoted verbatim.','availability':'Preserve actual release date/time/precision and original event provenance. Compute conservative first official session strictly after issuer-local release date from pinned local calendar; no same-day use or midnight substitution. Historical first-version/correction status remains explicitly separate from publication-date evidence.','conflicts':'Duplicate annual/current columns, ambiguous unit, percentage candidate, mismatched end, missing amount, changed source or unsupported period produce explicit gap/rejection. Never substitute another source or drop a pool member.','semantics':'This source schema is issuer_statement, not SEC us-gaap/GrossProfit. It never alters or bypasses the old frozen SEC plan.','output':'Extract every verifiable displayed raw pair with locators and independent-review flags; fully resolved facts and review-needed pairs are separate collections. No strategy admission implied.'},'implementation_and_validation':'Freeze this plan before executing value extraction. Bind extractor/test hashes in execution receipt. Synthetic tests must cover percentage/non-GAAP rejection, rowspan/colspan alignment, scale, dates, source hash mismatch and availability.','no_factor_calculation':True}
p=D/'EXTRACTION_PLAN.json'
